      if ($value -match '"'[A-Za-z]') { "'$latinFields += "$chunkName id=$($item.id) target.$($entry.Key)" }
    }
    foreach ($group in $item.group_items) {
      $value = $group.target
      if ($value -match '"'[\\u0980-\\u09FF]') { "'$bengaliCount++ }
      if ($value -match '"'\\uFFFD') { "'$replacementCount++ }
      if ($value -match '"'[\\u0660-\\u0669\\u06F0-\\u06F9\\u09E6-\\u09EF]') { "'$nonAsciiDigitCount++ }
      if ($value -match '"'[A-Za-z]') { "'$latinFields += "$chunkName id=$($item.id) group[$($group.group)].$($group.key)" }
    }
  }
}
"BENGALI_FIELDS=$bengaliCount"
"REPLACEMENT_FIELDS=$replacementCount"
"NON_ASCII_DIGIT_FIELDS=$nonAsciiDigitCount"
"LATIN_FIELDS=$($latinFields.Count)"
$latinFields'
